#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe ftp-mirror-a-folder-with-a-script. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site public public/css public/docs public/docs/2026
printf '%s\n' 'mirrors land under /mirror' > site/README.txt
printf '%s\n' '<h1>home</h1>' > public/index.html
printf '%s\n' 'body { margin: 0 }' > public/css/site.css
printf '%s\n' 'read me first' > public/docs/guide.txt
printf '%s\n' 'november' > public/docs/2026/notes.txt
cat > mirror.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# mirror.sh FOLDER URL: uploads every file under FOLDER to the FTP folder URL (ending in /) in one
# curl command, making folders as it goes and stopping at the first failure with curl's exit code;
# then lists each folder on the server. Names with spaces or characters a URL cannot hold are not handled.
src=$1; url=$2
set --
for f in $(cd "$src" && find . -type f | sort); do
  set -- "$@" -T "$src/${f#./}" "$url${f#./}"
done
curl -sS --ftp-create-dirs --fail-early -w "put %{url.path} %{exitcode}\n" "$@" || exit
for d in $(cd "$src" && find . -type d | sort); do
  d=${d#.}; d=${d#/}; d=${d:+$d/}
  echo "listing ./$d: $(curl -sS -l "$url$d" | tr -d '\r' | sort | tr '\n' ' ')"
done
EOF
surl --allow-anonymous --allow-uploads --list-directories --directory site ftp://127.0.0.1:8080/ &
sleep 1
sh mirror.sh public ftp://127.0.0.1:8080/mirror/
kill $(jobs -p)
